/* eslint no-console:0 import/extensions:0 */
import 'fantd/src/search/style/index.less';
import { Search } from "fantd";
import React from "react";
import ReactDOM from "react-dom";

class Component extends React.Component {

    constructor(){
        super();
        this.state={
            value: ''
        }
    }

    render() {
        return (
            <div style={{ margin: 10 }}>
                <Search placeholder="搜索" type="vague" />
                <Search placeholder="搜索" type='ghost' />
                <Search
                    value={this.state.value}
                    placeholder="搜索"
                    action
                    getNode={node =>{ this.searchNode = node}}
                    onInput={(value)=>{
                        this.setState({
                            value
                        })
                    }}
                    onAction={()=>{
                        this.setState({
                            value: ''
                        })
                    }}
                />
                <div
                    style={{cursor: 'pointer'}}
                    onClick={()=>{
                        this.searchNode.focus()
                    }}
                >获取焦点</div>
            </div>
        );
    }
}

ReactDOM.render(<Component />, document.getElementById("__react-content"));



